    def reconnect(self, request, isconnect=1):
        if isconnect == 1:
            return_info = self.init_connection()
            error_no = return_info['error_no']
            if error_no != SUCCESS:
                return (return_info, {})
        error_dict, response = self.login_account(op_branch_no=self.branch_no, op_entrust_way=self.entrust_way, op_station=self.op_station, password=self.password, account_content=self.operator_no, content_type=self.content_type, input_content='1', agw_account=self.agw_account, agw_password=self.agw_password)
        if error_dict['error_no'] == SUCCESS:
            request['user_token'] = self.user_token
        return (error_dict, request)
    def stock_order_response_transform(self, list_result):
        data_list = []
        for item in list_result:
            entrust_bs = item.get('entrust_bs')
            try:
                entrust_amount = float(item.get('entrust_amount', 0))
            except:
                entrust_amount = 0.0
            if entrust_bs == '1':
                amount = int(entrust_amount)
            elif entrust_bs == '2':
                amount = -int(entrust_amount)
            else:
                amount = 0
            order_time = del_order_time(str(item.get('report_time', '')))
            stock_code = f"{item.get('stock_code')!s}.{EXCHANGE_TYPES_DICT_REVERT[item.get('exchange_type')]!s}"
            error_info = item.get('error_info', '')
            if not '客户交易密码错误' in error_info:
                if len(re.findall(self.password_re, error_info)) > 0:
                    if self.trade_id is not None:
                        set_trade_stop_status(self.trade_id)
                        strategy_log.error('客户交易密码错误，终止交易')
                        raise
                    error_info = error_info.replace('错误', '错误，交易即将关闭')
                elif len(re.findall(self.token_re, error_info)) > 0:
                    error_info = error_info + '，交易即将关闭'
                if item.get('entrust_no_s', '') != '':
                    entrust_no_str = item.get('entrust_no_s')
                elif item.get('entrust_no', '') != '':
                    entrust_no_str = item.get('entrust_no')
                else:
                    entrust_no_str = item.get('entrust_no_str')
            data_item = {'entrust_no': entrust_no_str, 'order_time': order_time, 'stock_code': stock_code, 'amount': amount, 'price': float(item.get('entrust_price')), 'status': item.get('entrust_status'), 'business_amount': item.get('business_amount', 0), 'error_info': error_info, 'entrust_type': item.get('entrust_type'), 'entrust_prop': item.get('entrust_prop'), 'entrust_reference': item.get('entrust_reference', '')}
            data_list.append(data_item)
        else:
            return data_list
    def stock_trade_response_transform(self, list_result):
        data_list = []
        for item in list_result:
            status = item.get('entrust_status')
            try:
                business_amount = float(item.get('business_amount', 0))
            except:
                business_amount = 0.0
            if item.get('entrust_bs') == '1':
                amount = int(business_amount)
            elif item.get('entrust_bs') == '2':
                amount = -int(business_amount)
            else:
                amount = 0
            try:
                business_price = float(item.get('business_price', 0))
            except:
                business_price = 0.0
            date_str = str(item.get('init_date', '0'))
            if date_str == '0':
                date_str = datetime.datetime.now().strftime('%Y%m%d')
            business_time = del_order_time(str(item.get('business_time', '')), date_str)
            stock_code = f"{item.get('stock_code')!s}.{EXCHANGE_TYPES_DICT_REVERT[item.get('exchange_type')]!s}"
            withdraw_no = str(item.get('withdraw_no', '0'))
            if item.get('entrust_no_s', '') != '':
                entrust_no_str = item.get('entrust_no_s')
            elif item.get('entrust_no', '') != '':
                entrust_no_str = item.get('entrust_no')
            else:
                entrust_no_str = item.get('entrust_no_str')
            data_item = {'entrust_no': entrust_no_str, 'business_time': business_time, 'stock_code': stock_code, 'entrust_bs': item.get('entrust_bs'), 'business_amount': amount, 'business_price': business_price, 'business_balance': amount * business_price, 'business_id': item.get('business_id'), 'status': status, 'cancel_info': item.get('cancel_info', ''), 'withdraw_no': withdraw_no, 'entrust_reference': item.get('entrust_reference', ''), 'real_type': item.get('real_type'), 'real_status': item.get('real_status')}
            data_list.append(data_item)
        else:
            return data_list
    def strategy_signal_response_transform(self, list_result):
        data_list = []
        for item in list_result:
            stock_code = f"{item.get('stock_code')!s}.{EXCHANGE_TYPES_DICT_REVERT[item.get('exchange_type')]!s}"
            data_item = {'broker_id': item.get('broker_id'), 'create_date': item.get('create_date'), 'signal_provider_id': item.get('signal_provider_id'), 'signal_no': item.get('signal_no'), 'strategy_code': item.get('strategy_code'), 'stock_code': stock_code, 'entrust_bs': int(item.get('entrust_bs')), 'entrust_price': float(item.get('entrust_price', 0))}
            data_list.append(data_item)
        else:
            return data_list
