    def get_subcribe_param(self, topic_name):
        topic = getattr(self, topic_name, False)
        dict_sub_info = {'operator_no': f"QT_{self.fund_account!s}_{datetime.datetime.now().strftime('%H%M%S')!s}", 'trade_unit': self.operator_no, 'operator_pwd': self.password, 'topic_name': topic}
        if topic_name == 'STRATEGY_SIGNAL_RESPONSE':
            dict_filter = {}
        else:
            dict_filter = {'fund_account': self.fund_account}
        dict_filed = {'branch_no': self.branch_no_ex, 'fund_account': self.fund_account, 'password': self.password}
        return (topic, dict_sub_info, dict_filter, dict_filed)
